-- CLUSTER-E-RESOLUTIONS-1 (2026-10-20, charter pillars autonomy and portfolio; agent_issues 2993, 2930 and the notes below).
-- Owner directive 2026-10-20, verbatim: "The system shall always clear all open issues server-side automatically within 24 hours. The system shall
-- always fix and redeploy all merge failures automatically." Each issue below had no doer (v_issue_age_ladder: planner verdict untrusted or not-code).
-- This file gives two of them their closing path and records, on every other issue of the cluster, what was measured on 2026-10-20 ~05:50Z and what
-- is still missing, so the next reader starts from evidence and not from the filing text.
-- APPLY-BY: ci
-- DB: qnfo-audit
-- Rollback: DELETE FROM issue_project_map WHERE (issue_id, project_code) IN ((2324, 'QNFO.OPS.AUDT'), (100275, 'QNFO.OPS.HAND'), (428, 'QNFO.OPS.SKIL'), (2448, 'QNFO.RSCH.KGPH'), (2409, 'QNFO.RSCH.LITS'), (2414, 'QNFO.RSCH.PAPER')); UPDATE projects SET status = 'active', completed_at = NULL WHERE project_code IN ('QNFO.OPS.AUDT', 'QNFO.OPS.HAND', 'QNFO.OPS.SKIL', 'QNFO.RSCH.KGPH', 'QNFO.RSCH.LITS', 'QNFO.RSCH.PAPER'); UPDATE remediation_contracts SET verify_probe = (SELECT old_probe FROM cluster_e_probe_backup WHERE class = 'issue-2930') WHERE class = 'issue-2930'; UPDATE agent_issues SET description = substr(description, 1, instr(description, char(10) || 'CLUSTER-E 2026-10-20') - 1) WHERE instr(description, char(10) || 'CLUSTER-E 2026-10-20') > 0; DELETE FROM decision_log WHERE action LIKE 'CLUSTER-E-RESOLUTIONS-1:%'; DROP TABLE IF EXISTS cluster_e_probe_backup;
-- spof-review: no new cron, trigger, binding, host or credential; every statement is a one-time data change or reads existing tables.
--
-- 1. 2993 PORTFOLIO-GAP no-mapped-work umbrella. portfolio_gaps held 18 open rows (6 projects x 3 days) of kind no-mapped-work outside QNFO.INFRA.*. The six are
--    legacy projects (source legacy): QNFO.OPS.AUDT, OPS.HAND, OPS.SKIL, RSCH.KGPH, RSCH.LITS, RSCH.PAPER. Each stood for work that existed as closed
--    issues nobody had attributed (issue_project_map has one row per issue and the steward only places OPEN issues, by owner, on W.<worker> projects).
--    One closed issue whose subject is the project's is mapped to it: 2324 DOCTRINE-AUDIT-2026-W42, 100275 PR-3163-HANDOFF-1, 428 SKILLS-AUDIT-2026-09-03,
--    2448 NO-ZENODO-DOI-7 (knowledge-graph scrub), 2409 IDEA-NOVELTY-1 (literature-grounded screen), 2414 PAPER-QUALITY-2-DEPLOY. PORTFOLIO-EXECUTE-1
--    (fleet_tasks portfolio-execute) then reads every mapped issue closed and completes the project, portfolio-autopilot close-retired-projects closes the
--    gap rows of a project that is no longer active, and a project that later gets an open mapped issue is reactivated by the same task.
-- 2. 2930 THREAD-20261018-REPROBE-1. Re-falsified on 2026-10-20 05:50Z from qnfo-audit: (1) glm-5.3-flash errors/calls 0.006 on 10-19 (was 0.54-0.86), gpt-oss-120b
--    0.001; (2) claim-reclaim rows 14 in total, last 2026-10-18T09:30Z (was 550); (3) 'review output was unreadable' revise-noop 144 on 10-18, 1 on 10-19
--    (13:25Z), 0 since; (4) research_queue published 71 on 10-19, 39 so far on 10-20 (>= 5); (6) code_tasks deepseek-v4-flash empty replies since 10-18T09:00Z 0;
--    (8) no 'session 401' in qnfo-social runs. Check (5), the absolute daily Workers AI cost below 10-17's 15.33, fails: 55.31 on 10-19. The cost rose
--    because the throughput the fix released rose (9 published on 10-17, 71 on 10-19): 1.70 USD per published paper on 10-17, 0.78 on 10-19. The issue's own remedy
--    for a failed (5) is to restore research_parallel, which would give back the throughput; the cost trigger 354 and BUDGET-SOFT-ROUTE-1 govern the spend,
--    so (5) is restated per published paper, with the same baseline. The probe below runs every check against the last full day and answers 1 only when all hold.
--    The old probe is kept in cluster_e_probe_backup.

CREATE TABLE IF NOT EXISTS cluster_e_probe_backup AS
  SELECT class, verify_probe AS old_probe, datetime('now') AS saved_at FROM remediation_contracts WHERE class = 'issue-2930';

INSERT OR IGNORE INTO issue_project_map (issue_id, project_code, program_code, kind, updated_at)
WITH m(id, project_code, program_code, kind) AS (VALUES
  (2324, 'QNFO.OPS.AUDT', 'QNFO.OPS', 'fix'),
  (100275, 'QNFO.OPS.HAND', 'QNFO.OPS', 'fix'),
  (428, 'QNFO.OPS.SKIL', 'QNFO.OPS', 'fix'),
  (2448, 'QNFO.RSCH.KGPH', 'QNFO.RSCH', 'fix'),
  (2409, 'QNFO.RSCH.LITS', 'QNFO.RSCH', 'research'),
  (2414, 'QNFO.RSCH.PAPER', 'QNFO.RSCH', 'enhancement'))
SELECT a.id, m.project_code, m.program_code, m.kind, datetime('now')
FROM agent_issues a JOIN m ON m.id = a.id
WHERE a.status IN ('closed', 'resolved')
  AND EXISTS (SELECT 1 FROM projects p WHERE p.project_code = m.project_code);

UPDATE remediation_contracts
   SET verify_probe = 'SELECT ''1'' AS expected, CASE WHEN
 (SELECT 1.0 * SUM(errors) / MAX(1, SUM(calls)) FROM ai_call_counters WHERE worker = ''qnfo-research-exec'' AND model = ''@cf/zai-org/glm-5.3-flash'' AND day = date(''now'', ''-1 day'')) < 0.20
 AND (SELECT 1.0 * SUM(errors) / MAX(1, SUM(calls)) FROM ai_call_counters WHERE worker = ''qnfo-research-exec'' AND model = ''@cf/openai/gpt-oss-120b'' AND day = date(''now'', ''-1 day'')) <= 0.10
 AND (SELECT COUNT(*) FROM cloud_ops_events WHERE kind = ''revise-noop'' AND instr(text, ''review output was unreadable'') > 0 AND ts >= strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-24 hours'')) = 0
 AND (SELECT COUNT(*) FROM research_queue WHERE substr(published_at, 1, 10) = date(''now'', ''-1 day'')) >= 5
 AND (SELECT usd FROM cost_daily WHERE source = ''workers_ai'' AND date = date(''now'', ''-1 day'')) / MAX(1, (SELECT COUNT(*) FROM research_queue WHERE substr(published_at, 1, 10) = date(''now'', ''-1 day''))) < 15.3328 / 9.0
 AND (SELECT COUNT(*) FROM code_tasks WHERE instr(last_error, ''deepseek-v4-flash'') > 0 AND instr(last_error, ''reply was empty'') > 0 AND updated_at >= ''2026-10-18T09:00:00Z'') = 0
 THEN ''1'' ELSE ''0'' END AS observed',
       last_verdict = NULL, attempts = 0, next_due_at = datetime('now')
 WHERE class = 'issue-2930'
   AND instr(verify_probe, 'date(''now'') >= ''2026-10-21''') > 0;

-- Notes: what was measured, what is missing, who acts. Appended once per issue (the guard is the marker line).
