INSERT INTO decision_log (actor, assumption, action, evidence, outcome, blast_radius, rollback_path, capability_gain, predicted_outcome, reach_gain, surfaces_tested)
SELECT 'agent-cluster-e (session_01MQYeWxrMd4mVYPCphyaYes)',
  'an issue with no doer is cleared by giving it its closing path or by recording the measured blocker; a closing probe is corrected with evidence when its check measures the wrong quantity (METRIC-CLOSED-LOOP-1), never relaxed to pass',
  'CLUSTER-E-RESOLUTIONS-1: six closed issues mapped to the six legacy no-mapped-work projects; the issue-2930 probe restated per published paper; evidence notes on 20 issues',
